changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.quarantine_restore_chunks( p_tenant_id text, p_origin_collection text, p_quarantine_collection text, p_chashes text[], p_actor text, p_source_audit_id bigint, p_dry_run boolean ) RETURNS TABLE(r_chash text, r_outcome text, r_audit_id bigint, r_no_manifest boolean, r_reapable_after timestamptz) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE -- The default grace of the reapable predicate (vectors-021-2), for the report only; see the header. v_default_grace CONSTANT interval := interval '30 days'; v_now timestamptz := now(); v_requested text[]; v_restored text[] := '{}'::text[]; v_present text[]; v_dim_conflict text[]; v_missing text[]; v_no_manifest text[]; v_audit_id bigint; v_actor text; BEGIN IF p_chashes IS NULL OR cardinality(p_chashes) = 0 THEN RAISE EXCEPTION 'quarantine_restore_chunks: at least one chash is required' USING ERRCODE = 'invalid_parameter_value'; END IF; IF cardinality(p_chashes) > 5000 THEN RAISE EXCEPTION 'quarantine_restore_chunks: at most 5000 chashes per call, got %', cardinality(p_chashes) USING ERRCODE = 'invalid_parameter_value'; END IF; IF EXISTS (SELECT 1 FROM unnest(p_chashes) h WHERE h IS NULL OR h !~ '^[0-9a-f]{64}$') THEN RAISE EXCEPTION 'quarantine_restore_chunks: every chash must be 64 lowercase hex characters' USING ERRCODE = 'invalid_parameter_value'; END IF; IF p_origin_collection IS NULL OR p_origin_collection = '' OR left(p_origin_collection, 11) = 'quarantine-' THEN RAISE EXCEPTION 'quarantine_restore_chunks: the origin collection must be a non-quarantine collection, got %', p_origin_collection USING ERRCODE = 'invalid_parameter_value'; END IF; IF NOT EXISTS (SELECT 1 FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection) THEN RAISE EXCEPTION 'quarantine_restore_chunks: origin collection % is not registered for tenant % -- a chunk is restored into a registered collection, never into a name', p_origin_collection, p_tenant_id USING ERRCODE = 'invalid_parameter_value'; END IF; IF NOT EXISTS (SELECT 1 FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection AND cc.lifecycle_state = 'quarantine') THEN RAISE EXCEPTION 'quarantine_restore_chunks: % is not a registered quarantine collection for tenant %', p_quarantine_collection, p_tenant_id USING ERRCODE = 'invalid_parameter_value'; END IF;
-- The distinct requested chashes in first-seen order: the result carries one row per chash. SELECT array_agg(x.h ORDER BY x.ord) INTO v_requested FROM (SELECT u.h, min(u.ord) AS ord FROM unnest(p_chashes) WITH ORDINALITY AS u(h, ord) GROUP BY u.h) x;
IF p_dry_run THEN RETURN QUERY SELECT r.h, CASE WHEN o.chash IS NOT NULL AND q.chash IS NOT NULL AND (CASE WHEN o.embedding_384 IS NOT NULL THEN 384 WHEN o.embedding_768 IS NOT NULL THEN 768 WHEN o.embedding_1024 IS NOT NULL THEN 1024 END) IS DISTINCT FROM (CASE WHEN q.embedding_384 IS NOT NULL THEN 384 WHEN q.embedding_768 IS NOT NULL THEN 768 WHEN q.embedding_1024 IS NOT NULL THEN 1024 END) THEN 'dim_conflict' WHEN o.chash IS NOT NULL THEN 'present' WHEN q.chash IS NOT NULL THEN 'would_restore' ELSE 'missing' END, NULL::bigint, NULL::boolean, NULL::timestamptz FROM unnest(v_requested) WITH ORDINALITY AS r(h, ord) LEFT JOIN nexus.chunks o ON o.tenant_id = p_tenant_id AND o.collection = p_origin_collection AND o.chash = decode(r.h, 'hex') LEFT JOIN nexus.chunks q ON q.tenant_id = p_tenant_id AND q.collection = p_quarantine_collection AND q.chash = decode(r.h, 'hex') AND COALESCE(q.metadata->>'origin_collection', p_origin_collection) = p_origin_collection ORDER BY r.ord; RETURN; END IF;
PERFORM set_config('lock_timeout', '2000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_origin_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'quarantine_restore_chunks: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer holds it; retry', p_tenant_id, p_origin_collection USING ERRCODE = 'lock_not_available'; END;
-- THE MOVE: one statement, vectors-024's reaper_quarantine_chunks in reverse. The DELETE's WHERE skips a chash -- the origin already has (it is not deleted, so it stays in quarantine); the INSERT takes last_written_at = now() -- (see the header) and the carried created_at; ON CONFLICT DO NOTHING is the single-statement race's backstop. WITH req AS ( SELECT decode(r.h, 'hex') AS chash FROM unnest(v_requested) AS r(h) ), del AS ( DELETE FROM nexus.chunks q USING req WHERE q.tenant_id = p_tenant_id AND q.collection = p_quarantine_collection AND q.chash = req.chash AND COALESCE(q.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND NOT EXISTS (SELECT 1 FROM nexus.chunks o WHERE o.tenant_id = p_tenant_id AND o.collection = p_origin_collection AND o.chash = q.chash) RETURNING q.chash, q.chunk_text, q.embedding_384, q.embedding_768, q.embedding_1024, q.metadata, q.created_at ), ins AS ( INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, last_written_at) SELECT p_tenant_id, p_origin_collection, d.chash, d.chunk_text, d.embedding_384, d.embedding_768, d.embedding_1024, (COALESCE(d.metadata, '{}'::jsonb) - 'quarantined_at' - 'origin_collection'), d.created_at, v_now FROM del d ON CONFLICT (tenant_id, collection, chash) DO NOTHING RETURNING chash ) SELECT COALESCE(array_agg(encode(i.chash, 'hex') ORDER BY i.chash), '{}'::text[]) INTO v_restored FROM ins i;
-- Everything not restored is already in the origin (present, or dim_conflict when the quarantine copy is still -- there and holds a different width) or nowhere (missing). SELECT COALESCE(array_agg(c.h ORDER BY c.ord) FILTER (WHERE c.has_o AND NOT c.dim_differs), '{}'::text[]), COALESCE(array_agg(c.h ORDER BY c.ord) FILTER (WHERE c.has_o AND c.dim_differs), '{}'::text[]), COALESCE(array_agg(c.h ORDER BY c.ord) FILTER (WHERE NOT c.has_o), '{}'::text[]) INTO v_present, v_dim_conflict, v_missing FROM ( SELECT r.h, r.ord, o.chash IS NOT NULL AS has_o, (o.chash IS NOT NULL AND q.chash IS NOT NULL AND (CASE WHEN o.embedding_384 IS NOT NULL THEN 384 WHEN o.embedding_768 IS NOT NULL THEN 768 WHEN o.embedding_1024 IS NOT NULL THEN 1024 END) IS DISTINCT FROM (CASE WHEN q.embedding_384 IS NOT NULL THEN 384 WHEN q.embedding_768 IS NOT NULL THEN 768 WHEN q.embedding_1024 IS NOT NULL THEN 1024 END)) AS dim_differs FROM unnest(v_requested) WITH ORDINALITY AS r(h, ord) LEFT JOIN nexus.chunks o ON o.tenant_id = p_tenant_id AND o.collection = p_origin_collection AND o.chash = decode(r.h, 'hex') LEFT JOIN nexus.chunks q ON q.tenant_id = p_tenant_id AND q.collection = p_quarantine_collection AND q.chash = decode(r.h, 'hex') AND COALESCE(q.metadata->>'origin_collection', p_origin_collection) = p_origin_collection WHERE NOT (r.h = ANY (v_restored)) ) c;
-- Restored chunks with no own-collection manifest row: reapable again at v_now + the default grace. SELECT COALESCE(array_agg(r.h ORDER BY r.h), '{}'::text[]) INTO v_no_manifest FROM unnest(v_restored) AS r(h) WHERE NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = p_tenant_id AND m.collection = p_origin_collection AND m.chash = decode(r.h, 'hex'));
v_actor := COALESCE(NULLIF(left(btrim(p_actor), 256), ''), 'operator');
IF cardinality(v_restored) > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'quarantine_restore', p_origin_collection, v_actor, false, cardinality(v_restored), to_jsonb(v_restored), jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'source_audit_id', p_source_audit_id, 'requested', cardinality(v_requested), 'restored', cardinality(v_restored), 'present', cardinality(v_present), 'dim_conflict', cardinality(v_dim_conflict), 'missing', cardinality(v_missing), 'present_chashes', to_jsonb(v_present), 'dim_conflict_chashes', to_jsonb(v_dim_conflict), 'missing_chashes', to_jsonb(v_missing), 'no_manifest', cardinality(v_no_manifest), 'reapable_again_after', to_char(v_now + v_default_grace, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))) RETURNING id INTO v_audit_id; END IF;
RETURN QUERY SELECT r.h, CASE WHEN r.h = ANY (v_restored) THEN 'restored' WHEN r.h = ANY (v_dim_conflict) THEN 'dim_conflict' WHEN r.h = ANY (v_present) THEN 'present' ELSE 'missing' END, v_audit_id, CASE WHEN r.h = ANY (v_restored) THEN r.h = ANY (v_no_manifest) END, CASE WHEN r.h = ANY (v_no_manifest) THEN v_now + v_default_grace END FROM unnest(v_requested) WITH ORDINALITY AS r(h, ord) ORDER BY r.ord; END; $$;
GRANT EXECUTE ON FUNCTION nexus.quarantine_restore_chunks(text, text, text, text[], text, bigint, boolean) TO nexus_svc;
